import { autoUpdate, computePosition, flip, limitShift, MiddlewareState, offset, shift, size } from '@floating-ui/dom';
import { Component, ComponentInterface, Element, h, Host, Prop, Watch } from '@stencil/core';
import { PopoverPlacement } from '../../types';
import { handleAutofocus } from '../../utils/autofocus';

/**
 * @slot parent - parent which the popover refers to
 * @slot content - content of the popover
 */
@Component({
  tag: 'groupui-popover',
  styleUrl: 'popover.scss',
  shadow: true,
})
export class Popover implements ComponentInterface {
  /**
   * toggles visibility
   */
  @Prop({ reflect: true }) readonly visible: boolean = false;

  /**
   * content width is 100% of parent width
   */
  @Prop({ reflect: true }) readonly fullWidth: boolean;

  /**
   * content placement relative to the parent.
   * for a list of possible placements check https://popper.js.org/docs/v2/constructors/#options
   */
  @Prop({ reflect: true }) readonly placement: PopoverPlacement = 'bottom';

  /**
   * content offset relative to the parent (in pixel)
   */
  @Prop({ reflect: true }) readonly offset: number = 8;

  @Element() host: HTMLElement;

  private popoverRef: HTMLElement;
  private stopAutoUpdate: () => void;

  componentDidLoad() {
    if (!this.parent()) return;
    if (this.visible) {
      this.setContentInteractive();
      this.stopAutoUpdate = autoUpdate(this.parent(), this.popoverRef, this.updateContentPosition);
      this.onVisibleChanged();
      handleAutofocus(this.host);
    } else {
      this.updateContentPosition();
      this.setContentNonInteractive();
    }
  }

  private setContentNonInteractive() {
    this.popoverRef?.setAttribute('inert', 'true');
  }

  private setContentInteractive() {
    this.popoverRef?.removeAttribute('inert');
  }

  private updateContentPosition = () => {
    computePosition(this.parent(), this.popoverRef, {
      placement: this.placement,
      strategy: 'fixed',
      middleware: [
        offset(this.offset),
        flip(),
        shift({
          limiter: limitShift(),
        }),
        size(
          this.fullWidth && {
            apply(state: MiddlewareState) {
              Object.assign(state.elements.floating.style, {
                width: `${state.rects.reference.width}px`,
              });
            },
          }
        ),
      ],
    }).then(({ x, y }) => {
      Object.assign(this.popoverRef.style, {
        left: `${x}px`,
        top: `${y}px`,
      });
    });
  };

  @Watch('placement')
  onPlacementChanged() {
    this.updateContentPosition();
  }

  private parent(): HTMLElement | null {
    const parentSlot = this.host.shadowRoot.querySelector('slot[name="parent"]') as HTMLSlotElement;

    if (!parentSlot || parentSlot.assignedElements?.({ flatten: true }).length === 0) return null;

    return parentSlot.assignedElements?.({ flatten: true })[0] as HTMLElement;
  }

  @Watch('visible')
  onVisibleChanged() {
    if (this.visible) {
      this.setContentInteractive();
      if (this.parent()) {
        this.stopAutoUpdate = autoUpdate(this.parent(), this.popoverRef, this.updateContentPosition);
      }
      this.popoverRef.showPopover();
    } else {
      this.setContentNonInteractive();
      this.stopAutoUpdate && this.stopAutoUpdate();
      this.popoverRef.hidePopover();
    }
  }

  disconnectedCallback() {
    this.stopAutoUpdate && this.stopAutoUpdate();
  }

  render() {
    return (
      <Host>
        <slot name="parent" />
        <div class="content" ref={(el) => (this.popoverRef = el)} popover="manual">
          <slot name="content" />
        </div>
      </Host>
    );
  }
}
